#!/usr/bin/env bash
# Copies the server's projection vectors (generated by game-service, see
# libs/contracts/vectors/README.md) into the Flutter test fixtures.
# test/features/match/vectors_copy_test.dart fails while the copies differ.
set -euo pipefail
here="$(cd "$(dirname "$0")/.." && pwd)"
src="$here/../../libs/contracts/vectors"
dst="$here/test/fixtures/vectors"
mkdir -p "$dst"
rm -f "$dst"/*.json
cp "$src"/*.json "$dst"/
echo "copied $(ls "$dst"/*.json | wc -l | tr -d ' ') vectors to test/fixtures/vectors"
